{
  "focus_areas": [
    "Lowering LDL cholesterol with more soluble fibre and healthier fats",
    "Bringing down triglycerides by cutting refined carbs, fried foods and added sugars",
    "Heart-healthy vegetarian eating built around Indian foods (dal, millets, seasonal sabzi, sprouts)",
    "Regular physical activity and weight/waist management",
    "Cardiology review and repeat fasting lipid profile as advised by your doctor"
  ],
  "diet_recommendations": [
    {
      "item": "Start the day with 40–50 g plain oats (or 2 ragi/jowar dosas or 1 bowl vegetable dalia), cooked with water or 100 ml low-fat milk, plus 1 tbsp ground flaxseed stirred in at breakfast.",
      "rationale": "Oats and flaxseed provide soluble fibre and plant omega-3 that help lower LDL. Keep it unsweetened; add cinnamon or a few chopped apple pieces instead of sugar.",
      "linked_biomarker": "ldl"
    },
    {
      "item": "At lunch and dinner, have 1 katori (150 g cooked) of dal, rajma, chana or lobia, and 2 phulkas made from bajra, jowar, ragi or whole-wheat atta instead of white rice/maida rotis.",
      "rationale": "Whole pulses and millets are high in fibre and slowly digested, which helps reduce triglycerides and keeps you full. Limit white rice to 1 small katori if you have it at all.",
      "linked_biomarker": "triglycerides"
    },
    {
      "item": "Eat 1 cup of raw salad (cucumber, tomato, onion, carrot, cabbage, lemon, chaat masala without extra salt) and 1 katori of seasonal sabzi at both lunch and dinner, using only 1–2 tsp oil per sabzi.",
      "rationale": "Vegetables add fibre and antioxidants with very few calories, and cutting cooking oil lowers total fat intake, which supports lowering total cholesterol.",
      "linked_biomarker": "total_cholesterol"
    },
    {
      "item": "Snack on 4–5 almonds + 2 walnuts (unsalted, about 15 g total) or 1 cup of moong sprouts chaat with lemon and onion in the evening, instead of fried snacks.",
      "rationale": "A small daily handful of nuts improves the LDL-to-HDL balance and replaces deep-fried snacks that push triglycerides up.",
      "linked_biomarker": "ldl"
    },
    {
      "item": "Include 100 g paneer made from low-fat milk or 100 g tofu 3–4 times a week, and 1 katori low-fat curd daily; use only 3–4 tsp of mustard, rice bran or olive oil per day for the whole family's cooking.",
      "rationale": "Lean plant and low-fat dairy protein keeps you full without adding saturated fat, and keeping total visible oil low helps reduce total cholesterol.",
      "linked_biomarker": "total_cholesterol"
    },
    {
      "item": "Finish dinner by 8:00–8:30 pm and keep a 12-hour overnight gap before breakfast; have a small fruit or 4–5 almonds if you feel hungry after dinner.",
      "rationale": "An earlier, lighter dinner and a longer overnight fast help the body clear triglyceride-rich lipoproteins from the blood.",
      "linked_biomarker": "triglycerides"
    }
  ],
  "foods_to_avoid": [
    "Deep-fried foods such as samosa, pakora, vada, puri, bhatura and fried namkeen",
    "Bakery items made with maida and vanaspati or butter — biscuits, khari, puff pastry, cakes and rusk",
    "Sweets and mithai, including those made with ghee, khoya or jaggery, and sugar in tea/coffee",
    "Sweetened drinks, packaged fruit juices, cold drinks and energy drinks",
    "Large portions of white rice, maida rotis and refined-flour idli/dosa at every meal",
    "Reusing the same oil for frying more than once; avoid palm oil and margarine",
    "Full-fat cream, butter and large amounts of ghee or coconut oil in daily cooking",
    "Alcohol, if you drink — it raises triglycerides significantly"
  ],
  "activity": "Aim for 30–40 minutes of brisk walking 5 days a week (about 150 minutes total), building up gradually from 15 minutes if you are not used to it, plus 2 days of simple bodyweight strength work such as squats, wall push-ups and light resistance bands. Add 10 minutes of stretching or yoga in the evening. Your doctor has not restricted exercise, but if you feel chest discomfort, breathlessness or dizziness, stop and seek medical advice; always follow your doctor's advice first.",
  "sleep": "Sleep 7–8 hours on a fixed schedule, lights out by 10:30–11:00 pm. Keep screens off for 30 minutes before bed, avoid tea/coffee after 4 pm, and keep the room dark and cool. Poor sleep worsens lipid and blood sugar control.",
  "retest_in_weeks": 12
}
